const $=id=>document.getElementById(id);let questions=[],list=[],index=0,topic='All topics',revealed=false;
const KEY='jiki-practice-v1';let state={ratings:{},bookmarks:[],notes:{},last:null};try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object')state={...state,...saved};if(!state.ratings||typeof state.ratings!=='object')state.ratings={};if(!Array.isArray(state.bookmarks))state.bookmarks=[];if(!state.notes||typeof state.notes!=='object')state.notes={}}catch{}
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{$('markStatus').textContent='Browser storage is unavailable; this session’s progress may not be saved.'}};
function updateStats(){const n=questions.filter(q=>state.ratings[q.id]==='known').length;$('learnedTotal').replaceChildren(document.createTextNode(String(n)));const s=document.createElement('span');s.textContent=' / 500';$('learnedTotal').append(s);$('overallProgress').value=n}
function topics(){const names=['All topics',...new Set(questions.map(q=>q.topic))];$('topicFilters').replaceChildren();for(const t of names){const b=document.createElement('button');b.textContent=t;b.className=t===topic?'active':'';b.setAttribute('aria-pressed',String(t===topic));const count=document.createElement('span');count.textContent=t==='All topics'?questions.length:questions.filter(q=>q.topic===t).length;b.append(count);b.onclick=()=>{topic=t;topics();filter()};$('topicFilters').append(b)}}
function filter(){const words=$('questionSearch').value.toLowerCase().trim().split(/\s+/).filter(Boolean),mode=$('studyFilter').value;list=questions.filter(q=>(topic==='All topics'||q.topic===topic)&&words.every(w=>(q.prompt+' '+q.structure+' '+q.topic+' '+q.id).toLowerCase().includes(w))&&(mode==='all'||mode==='new'&&!state.ratings[q.id]||mode==='saved'&&state.bookmarks.includes(q.id)||state.ratings[q.id]===mode));index=0;render()}
function closeModel(){$('modelPanel').hidden=true;$('modelFrameHost').replaceChildren()}
function render(){closeModel();revealed=false;$('answerPanel').hidden=true;$('revealAnswer').hidden=false;$('questionCard').hidden=!list.length;$('emptyState').hidden=!!list.length;$('resultCount').textContent=list.length+' questions in this list';$('questionPosition').textContent=list.length?`${index+1} / ${list.length}`:'0 / 0';$('previousQuestion').disabled=!list.length||index===0;$('nextQuestion').disabled=!list.length||index===list.length-1;$('nextBottom').disabled=$('nextQuestion').disabled;if(!list.length)return;const q=list[index];$('questionId').textContent=q.id+' / ANATOMY RECALL';$('questionTopic').textContent=q.topic;$('questionKind').textContent=q.kind;$('questionPrompt').textContent=q.prompt;$('ownAnswer').value=state.notes[q.id]||'';$('correctAnswer').textContent=q.answer;$('answerExplanation').textContent=q.explanation;$('referenceLink').href=q.source;$('referenceLink').textContent=q.sourceName+' ↗';$('modelName').textContent=q.structure;$('modelNote').textContent=q.modelNote;$('markStatus').textContent=state.ratings[q.id]==='known'?'Marked as understood.':state.ratings[q.id]==='review'?'Saved for revision.':'';bookmark();state.last=q.id;persist();const u=new URL(location);u.searchParams.set('q',q.id);if(topic==='All topics')u.searchParams.delete('topic');else u.searchParams.set('topic',topic);history.replaceState(null,'',u);updateStats()}
function bookmark(){const q=list[index];if(!q)return;const active=state.bookmarks.includes(q.id);$('bookmarkQuestion').setAttribute('aria-pressed',String(active));$('bookmarkQuestion').textContent=active?'Bookmarked ✓':'Bookmark'}
function move(delta){if(!list.length)return;index=Math.max(0,Math.min(list.length-1,index+delta));render();$('questionPrompt').focus({preventScroll:true})}
function rate(value){if(!revealed||!list[index])return;state.ratings[list[index].id]=value;persist();updateStats();$('markStatus').textContent=value==='known'?'Marked as understood. Continue when you are ready.':'Saved to Needs revision. Continue when you are ready.'}
$('questionSearch').oninput=filter;$('studyFilter').onchange=filter;$('previousQuestion').onclick=()=>move(-1);$('nextQuestion').onclick=$('nextBottom').onclick=()=>move(1);$('revealAnswer').onclick=()=>{revealed=true;$('answerPanel').hidden=false;$('revealAnswer').hidden=true};$('ownAnswer').oninput=()=>{if(list[index]){state.notes[list[index].id]=$('ownAnswer').value;persist()}};$('markKnown').onclick=()=>rate('known');$('markReview').onclick=()=>rate('review');$('bookmarkQuestion').onclick=()=>{const id=list[index]?.id;if(!id)return;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(v=>v!==id):[...state.bookmarks,id];persist();bookmark()};$('shuffleQuestions').onclick=()=>{for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}index=0;render()};$('resetFilters').onclick=()=>{topic='All topics';$('questionSearch').value='';$('studyFilter').value='all';topics();filter()};$('clearProgress').onclick=()=>{if(!confirm('Clear your practice ratings, notes and bookmarks in this browser?'))return;state={ratings:{},bookmarks:[],notes:{},last:null};persist();filter()};$('showModel').onclick=()=>{const q=list[index];closeModel();$('modelPanel').hidden=false;$('selectedModelName').textContent=q.structure;$('openFullModel').href=q.url;const frame=document.createElement('iframe');frame.title='Interactive 3D reference: '+q.structure;frame.src=q.url+'&embed=1';$('modelFrameHost').append(frame);$('modelPanel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})};$('closeModel').onclick=closeModel;
async function init(){$('questionError').hidden=true;try{const r=await fetch('questions.json');if(!r.ok)throw Error('Question data unavailable');const data=await r.json();if(data.questions.length!==500)throw Error('Unexpected bank size');questions=data.questions;topics();const initial=new URLSearchParams(location.search),requested=initial.get('q')||state.last,requestedTopic=initial.get('topic');if(requestedTopic&&questions.some(q=>q.topic===requestedTopic))topic=requestedTopic;topics();filter();const found=list.findIndex(q=>q.id===requested);if(found>=0){index=found;render()}}catch(e){$('questionError').hidden=false;$('questionCard').hidden=true;$('emptyState').hidden=true;$('resultCount').textContent='Questions unavailable';console.error(e)}}$('retryQuestions').onclick=init;init();
